import {NoteIcon, PeopleIcon, RepoIcon, TagIcon} from '@primer/octicons-react'
import {AsyncSuggestionsFilterProvider} from './async-suggestions-filter-provider'
import type {FilterKey, SuppliedFilterProviderOptions} from '@github-ui/filter'

export class RepositoryFilterProvider extends AsyncSuggestionsFilterProvider {
  constructor({path}: {path: string}, options?: SuppliedFilterProviderOptions) {
    super(
      {
        displayName: 'Repository',
        key: 'repo',
        priority: 1,
        icon: RepoIcon,
        description: 'Find alerts for the selected repositories',
      } as FilterKey,
      path,
      options,
    )
  }
}

